-- ============================================
-- LUMA — Thème 2 : scénario MOYEN 2/3 x4 — Une conversation qui dévie sur un sujet sensible
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "So, are you following the election coverage lately?", "text_fr": "Alors, tu suis l''actualité des élections en ce moment ?", "choices": [{"text": "A little, but I try not to get too deep into politics on dates.", "text_fr": "Un peu, mais j''évite d''aller trop loin dans la politique en rendez-vous.", "next": "n2"}, {"text": "Yeah, actually — it''s been pretty intense lately.", "text_fr": "Ouais, en fait — ça a été assez intense dernièrement.", "next": "n2b"}]}, "n2": {"speaker": "alex", "text": "Fair enough, ha. What do you usually talk about on dates then?", "text_fr": "Entendu, ha. Tu parles de quoi habituellement en rendez-vous alors ?", "choices": [{"text": "Travel, food, silly hobbies — the fun stuff.", "text_fr": "Voyages, nourriture, hobbies rigolos — les trucs fun.", "next": "n3"}]}, "n2b": {"speaker": "alex", "text": "Yeah, I have some pretty strong opinions on it, honestly.", "text_fr": "Ouais, j''ai des opinions assez tranchées là-dessus, honnêtement.", "choices": [{"text": "I''m curious what you think, though I might not fully agree.", "text_fr": "Je suis curieux de savoir ce que tu penses, même si je ne serai peut-être pas d''accord.", "next": "n3b"}, {"text": "I''d rather steer away from that topic tonight, if that''s okay.", "text_fr": "Je préférerais éviter ce sujet ce soir, si ça te va.", "next": "n3c"}]}, "n3": {"speaker": "alex", "text": "Ha, fair. Though I do think it''s important to know where someone stands eventually.", "text_fr": "Ha, entendu. Même si je pense que c''est important de savoir où quelqu''un se situe éventuellement.", "choices": [{"text": "I agree, just maybe not on a first date.", "text_fr": "Je suis d''accord, juste peut-être pas au premier rendez-vous.", "next": "n4"}]}, "n3b": {"speaker": "alex", "text": "(Shares a strong opinion that you don''t fully agree with.)", "text_fr": "(Partage une opinion tranchée avec laquelle tu n''es pas totalement d''accord.)", "choices": [{"text": "I see your point, but I look at it a bit differently.", "text_fr": "Je comprends ton point de vue, mais je vois ça un peu différemment.", "next": "n4b"}, {"text": "Interesting perspective — I hadn''t thought of it that way.", "text_fr": "Perspective intéressante — je n''y avais pas pensé comme ça.", "next": "n4c"}]}, "n3c": {"speaker": "alex", "text": "Of course, no problem at all. I didn''t mean to make things tense.", "text_fr": "Bien sûr, aucun problème. Je ne voulais pas rendre les choses tendues.", "choices": [{"text": "You didn''t, I just prefer lighter topics for now.", "text_fr": "Tu ne l''as pas fait, je préfère juste des sujets plus légers pour l''instant.", "next": "n4"}]}, "n4": {"speaker": "alex", "text": "Makes sense. So, tell me about your favorite trip ever.", "text_fr": "Ça se comprend. Alors, dis-moi ton meilleur voyage.", "choices": [{"text": "(The conversation moves comfortably to lighter topics.)", "text_fr": "(La conversation glisse confortablement vers des sujets plus légers.)", "next": "n6"}]}, "n4b": {"speaker": "alex", "text": "That''s a fair point, actually. I hadn''t considered that angle.", "text_fr": "C''est un point valable, en fait. Je n''avais pas considéré cet angle.", "choices": [{"text": "I appreciate you being open to it.", "text_fr": "J''apprécie que tu sois ouvert à ça.", "next": "n5"}]}, "n4c": {"speaker": "alex", "text": "Yeah? I appreciate you actually listening instead of arguing.", "text_fr": "Ouais ? J''apprécie que tu écoutes vraiment au lieu de débattre.", "choices": [{"text": "I think disagreeing respectfully is healthy, honestly.", "text_fr": "Je pense que ne pas être d''accord avec respect c''est sain, honnêtement.", "next": "n5"}]}, "n5": {"speaker": "alex", "text": "I really respect that about you — not everyone can disagree without getting heated.", "text_fr": "Je respecte vraiment ça chez toi — tout le monde ne peut pas être en désaccord sans s''échauffer.", "choices": [{"text": "Same goes for you, I appreciate the openness.", "text_fr": "Pareil pour toi, j''apprécie l''ouverture d''esprit.", "next": "n6"}]}, "n6": {"speaker": "alex", "text": "Anyway, enough heavy topics — what''s the best trip you''ve ever taken?", "text_fr": "Bref, assez de sujets lourds — c''est quoi le meilleur voyage que t''aies fait ?", "choices": [{"text": "A backpacking trip through Portugal, it was incredible.", "text_fr": "Un voyage sac à dos au Portugal, c''était incroyable.", "next": "n7"}, {"text": "Honestly, a quiet cabin trip with just my family.", "text_fr": "Honnêtement, un séjour tranquille en cabane juste avec ma famille.", "next": "n7"}]}, "n7": {"speaker": "alex", "text": "That sounds amazing. I''d love to hear more about it sometime.", "text_fr": "Ça a l''air génial. J''aimerais en savoir plus un jour.", "choices": [{"text": "I''d love to tell you more, over another coffee maybe?", "text_fr": "J''aimerais bien t''en dire plus, autour d''un autre café peut-être ?", "next": "n8"}, {"text": "Definitely, there''s a lot more to share.", "text_fr": "Carrément, il y a beaucoup plus à raconter.", "next": "n8"}]}, "n8": {"speaker": "alex", "text": "I''d really like that. Despite the detour, this has been a great conversation.", "text_fr": "J''aimerais vraiment ça. Malgré le détour, c''était une super conversation.", "choices": [{"text": "Agreed — I think we handled that well together.", "text_fr": "D''accord — je pense qu''on a bien géré ça ensemble.", "next": "end_handled"}, {"text": "It really has, I''m glad we could navigate that topic okay.", "text_fr": "Vraiment, je suis content qu''on ait pu naviguer ce sujet sans souci.", "next": "end_handled"}]}, "end_handled": {"speaker": "alex", "text": "Exactly. It''s a good sign when you can disagree and still enjoy each other''s company.", "text_fr": "Exactement. C''est bon signe quand on peut être en désaccord et quand même apprécier la compagnie de l''autre.", "end": true, "ending_label": "Désaccord géré avec maturité et respect 🤝"}}}'::jsonb, is_playable = true
where title = 'Une conversation qui dévie sur un sujet sensible'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
